    if ismember('weizmann',inter.relaxation)&&...
       ((~isfield(inter,'weiz_r1d'))||(~isfield(inter,'weiz_r2d')))
        error('R1d and R2d rates must be specified with Weizmann DNP relaxation theory.');
    end

