Hz=Hz/norm(Hz,2); Fz=Fz/norm(Fz,2);
HzFz=HzFz/norm(HzFz,2); 

% Get the Hamiltonian
H=hamiltonian(assume(spin_system,'nmr'));

% Get relaxation matrix
R=relaxation(spin_system);

% Thermalise R to Hz+Fz
R(1,1)=1; R(:,1)=-R*(Hz+Fz);

