% Internal consistency test for the state vectors and matrices
% in each of the three formalisms supported by Spinach.
%
% i.kuprov@soton.ac.uk

function normalization_1()

% System specification
sys.magnet=14.1;
sys.isotopes={'1H','235U'};
inter.zeeman.scalar={2.5 1.0};
inter.coupling.scalar{1,2}=10;
inter.coupling.scalar{2,1}=10;
spin_system=create(sys,inter);

% Preallocate the answer
norm_diffs=zeros(6,3,'like',1i);

% Compute norm differences
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
for n=1:numel(formalisms)
    bas.formalism=formalisms{n};
    bas.approximation='none';
    spin_system=basis(spin_system,bas);
    Ux=state(spin_system,'Lx','235U');
    Uy=state(spin_system,'Ly','235U');
    Uz=state(spin_system,'Lz','235U');
    Hx=state(spin_system,'Lx','1H');
    Hy=state(spin_system,'Ly','1H');
    Hz=state(spin_system,'Lz','1H');
    norm_diffs(1,n)=norm(full(Ux))-norm(full(Uy));
    norm_diffs(2,n)=norm(full(Uy))-norm(full(Uz));
    norm_diffs(3,n)=norm(full(Uz))-norm(full(Ux));
    norm_diffs(4,n)=norm(full(Hx))-norm(full(Hy));
    norm_diffs(5,n)=norm(full(Hy))-norm(full(Hz));
    norm_diffs(6,n)=norm(full(Hz))-norm(full(Hx));
end

% Display the answers
if any(abs(norm_diffs)>1e-6,'all')
    error('Internal norm consistency test FAILED.');
else
    disp('Internal norm consistency test PASSED.');
end

end

====
% Internal consistency test for the state vectors and matrices.
% Checks that the inner products are consistent between the for-
% malisms supported by Spinach. Output should be a 6x3 matrix
% with identical columns.
%
% i.kuprov@soton.ac.uk
% ledwards@cbs.mpg.de

function normalization_2()

% System specification
sys.magnet=14.1;
sys.isotopes={'1H','235U'};
inter.zeeman.scalar={2.5 1.0};
inter.coupling.scalar{1,2}=10;
inter.coupling.scalar{2,1}=10;
spin_system=create(sys,inter);

% Preallocate the answer
norms=zeros(6,3,'like',1i);

% Get the norms
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
for n=1:numel(formalisms)
    bas.formalism=formalisms{n};
    bas.approximation='none';
    spin_system=basis(spin_system,bas);
    Ux=state(spin_system,'Lx','235U');
    Uy=state(spin_system,'Ly','235U');
    Uz=state(spin_system,'Lz','235U');
    Hx=state(spin_system,'Lx','1H');
    Hy=state(spin_system,'Ly','1H');
    Hz=state(spin_system,'Lz','1H');
    norms(1,n)=trace(full(Ux)'*full(Ux));
    norms(2,n)=trace(full(Uy)'*full(Uy));
    norms(3,n)=trace(full(Uz)'*full(Uz));
    norms(4,n)=trace(full(Hx)'*full(Hx));
    norms(5,n)=trace(full(Hy)'*full(Hy));
    norms(6,n)=trace(full(Hz)'*full(Hz));
end

% Run the tests
mult_factor=prod(spin_system.comp.mults);
if norm(norms(:,1)-norms(:,2),1)>1e-6||...
   norm(norms(:,1)-mult_factor*norms(:,3),1)>1e-6
    error('Cross-formalism state norm test FAILED.');
else
    disp('Cross-formalism state norm test PASSED.');
end

end

% Observables at thermal equilibrium using the three formalisms 
% supported by Spinach kernel, tested against known answers.
%
% i.kuprov@soton.ac.uk

function thermal_equilibrium_1()

% Spin system parameters
sys.magnet=14.1;
sys.isotopes={'E','1H','14N','15N'};
inter.zeeman.scalar={2.0023 1.0 2.0 3.0};
inter.coupling.scalar=cell(length(sys.isotopes));
inter.coupling.scalar{1,2}=1e6;
inter.coupling.scalar{2,3}=1e6;
inter.coupling.scalar{1,3}=1e3;
inter.coupling.scalar{3,4}=1e3;
inter.coupling.scalar{1,4}=1e2;
inter.temperature=4.2;

% Preallocate the answers
eq_mags_spinach=zeros(4,3,'like',1i);
eq_mags_textbook=zeros(4,1,'like',1i);

% Get numerical equilibrium magnetisation
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
for n=1:numel(formalisms)
    bas.formalism=formalisms{n};
    bas.approximation='none';
    spin_system=create(sys,inter);
    spin_system=basis(spin_system,bas);
    rho=equilibrium(spin_system,hamiltonian(assume(spin_system,'labframe'),'left'));
    eq_mags_spinach(1,n)=trace(state(spin_system,'Lz','E')'*rho);
    eq_mags_spinach(2,n)=trace(state(spin_system,'Lz','1H')'*rho);
    eq_mags_spinach(3,n)=trace(state(spin_system,'Lz','14N')'*rho);
    eq_mags_spinach(4,n)=trace(state(spin_system,'Lz','15N')'*rho);
end

% Get analytical equilibrium magnetisation
[~,P]=levelpop('E',sys.magnet,inter.temperature);
eq_mags_textbook(1)=0.5*P(1)-0.5*P(2);
[~,P]=levelpop('1H',sys.magnet,inter.temperature);
eq_mags_textbook(2)=0.5*P(1)-0.5*P(2);
[~,P]=levelpop('14N',sys.magnet,inter.temperature);
eq_mags_textbook(3)=P(1)-P(3);
[~,P]=levelpop('15N',sys.magnet,inter.temperature);
eq_mags_textbook(4)=0.5*P(1)-0.5*P(2);

% Display the answers
if any(abs(eq_mags_spinach-eq_mags_textbook)>1e-5,'all')
    error('Cross-formalism thermal equilibrium test FAILED.');
else
    disp('Cross-formalism thermal equilibrium test PASSED.');
end

end

