addpath(genpath('/workspace/task/source'));
addpath(genpath('/workspace/task/fixtures'));
addpath('/workspace/task/fixtures/public/octave_compat');
function H=physical_left_hamiltonian(spin_system)
nspins=spin_system.comp.nspins;
H=0*operator(spin_system,'E',1,'left');
for n=1:nspins
    omega=trace(spin_system.inter.zeeman.matrix{n})/3;
    H=H+omega*operator(spin_system,'Lz',n,'left');
end
axes={'Lx','Ly','Lz'};
for n=1:nspins
    for k=(n+1):nspins
        if isempty(spin_system.inter.coupling.matrix{n,k}), continue; end
        coupling=trace(spin_system.inter.coupling.matrix{n,k})/3;
        for a=1:numel(axes)
            H=H+coupling*operator(spin_system,{axes{a},axes{a}},{n,k},'left');
        end
    end
end
end
res=zeros(2,2);
for fi=1:2
  formalism={'sphten-liouv','zeeman-liouv'}{fi};
  ss=task015_public_system(formalism);
  H=physical_left_hamiltonian(ss); rho=equilibrium(ss,H); R=relaxation(ss);
  coil=state(ss,'Lz','19F');
  fprintf('%s before %.16g normrho %.16g\n',formalism,trace(coil'*rho),norm(rho));
  for mi=1:2
    method={'dibari','IME'}{mi};
    if strcmp(method,'IME'), Rt=thermalize(ss,R,[],[],rho,'IME');
    else, Rt=thermalize(ss,R,H,ss.rlx.temperature,[],method); end
    ev=step(ss,1i*Rt,rho,0.01);
    res(fi,mi)=trace(coil'*ev);
    fprintf('  %s after %.16g diff %.3g\n',method,res(fi,mi),abs(res(fi,mi)-trace(coil'*rho)));
  end
end
fprintf('cross dibari %.3g cross IME %.3g\n',abs(res(1,1)-res(2,1)),abs(res(1,2)-res(2,2)));
EOF
